INSERT INTO SUPPLYCHAINIQ_COCO.EVALUATION.SEMANTIC_SMOKE_TESTS VALUES
('SMK-001','Enterprise OTD','SELECT ROUND(100.0 * COUNT_IF(DELIVERY_STATUS IN (''Advance shipping'',''Shipping on time'')) / NULLIF(COUNT_IF(DELIVERY_STATUS != ''Shipping canceled''), 0), 6) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','42.710040'),
('SMK-002','Enterprise delay rate','SELECT ROUND(100.0 * COUNT_IF(DELIVERY_STATUS = ''Late delivery'') / NULLIF(COUNT_IF(DELIVERY_STATUS != ''Shipping canceled''), 0), 6) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','57.289960'),
('SMK-003','Enterprise sales','SELECT ROUND(SUM(SALES), 6) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','36784735.01338'),
('SMK-004','Enterprise profit','SELECT ROUND(SUM(ORDER_PROFIT_PER_ORDER), 6) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','3966902.97405'),
('SMK-005','Enterprise profit margin','SELECT ROUND(100.0 * SUM(ORDER_PROFIT_PER_ORDER) / NULLIF(SUM(SALES), 0), 6) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','10.784101'),
('SMK-006','Enterprise shipment count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.SCMS_SHIPMENT_FACT','10324'),
('SMK-007','Enterprise freight cost','SELECT ROUND(SUM(FREIGHT_COST_USD), 2) FROM SUPPLYCHAINIQ_COCO.CORE.SCMS_SHIPMENT_FACT','68817849.41'),
('SMK-008','Enterprise logistics rate','SELECT ROUND(100.0 * SUM(FREIGHT_COST_USD) / NULLIF(SUM(LINE_ITEM_VALUE), 0), 6) FROM SUPPLYCHAINIQ_COCO.CORE.SCMS_SHIPMENT_FACT','4.22822'),
('SMK-009','DataCo order item count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','180519'),
('SMK-010','DataCo distinct orders','SELECT COUNT(DISTINCT ORDER_ID) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','65752'),
('SMK-011','DataCo distinct customers','SELECT COUNT(DISTINCT CUSTOMER_ID) FROM SUPPLYCHAINIQ_COCO.CORE.ORDER_ITEM_FACT','20652'),
('SMK-012','Customer dim row count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.CUSTOMER_DIM','20652'),
('SMK-013','Product dim row count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.PRODUCT_DIM','118'),
('SMK-014','Supplier dim row count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.SUPPLIER_DIM','73'),
('SMK-015','Manufacturing site dim count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.MANUFACTURING_SITE_DIM','88'),
('SMK-016','Geography dim country count','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.CORE.GEOGRAPHY_DIM','165'),
('SMK-017','Enterprise scorecard single row','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.SEMANTIC.ENTERPRISE_DELIVERY_SCORECARD','1'),
('SMK-018','Country logistics grain','SELECT COUNT(*) FROM SUPPLYCHAINIQ_COCO.SEMANTIC.COUNTRY_LOGISTICS_SCORECARD','43'),
('SMK-019','Belize logistics rate anchor','SELECT ROUND(LOGISTICS_COST_RATE_PCT, 6) FROM SUPPLYCHAINIQ_COCO.SEMANTIC.COUNTRY_LOGISTICS_SCORECARD WHERE COUNTRY = ''Belize''','311.049206'),
('SMK-020','Logistics rate formula consistency','SELECT ROUND(100.0 * SUM(FREIGHT_COST_USD) / NULLIF(SUM(LINE_ITEM_VALUE), 0), 5) FROM SUPPLYCHAINIQ_COCO.CORE.SCMS_SHIPMENT_FACT','4.22822');
